python -I -c "
import os,re,collections,json
src=r'<RAW>\客戶案件'
files=[]
for r,_,fs in os.walk(src):
    for f in fs: files.append(os.path.join(r,f))
print('source files',len(files))
idx=r'<V>\檔案索引\客戶案件'
cards=[]
for r,_,fs in os.walk(idx):
    for f in fs:
        if f.endswith('.md'): cards.append(os.path.join(r,f))
print('cards',len(cards))
ids=collections.Counter(); bad=[]
for c in cards:
    t=open(c,encoding='utf-8',errors='replace').read()
    m=re.search(r'^編號:\s*(f-\w+)',t,re.M)
    h=t.startswith('---') and t.count('\n---')>=1
    if not m or not h: bad.append(c)
    else: ids[m.group(1)]+=1
    for k in ('標題: （填）','卡型: （填）','讀取: （填'):
        if k in t: bad.append((c,k))
print('dup ids',[i for i,n in ids.items() if n>1])
print('bad',bad[:10],len(bad))
d=json.load(open(r'<OUT>\tool-results\bl3uykzhj.txt',encoding='utf-8'))
newids={x['id'] for x in d['new']}
print('new∩carded',len(newids&set(ids)))
print('by folder source',collections.Counter(os.path.relpath(f,src).split(os.sep)[0] for f in files))
print('by folder cards',collections.Counter(os.path.relpath(c,idx).split(os.sep)[0] for c in cards))
"

